/**
 * Whether an order contains any of the given product or variation IDs.
 *
 * @param WC_Order|int $order       Order object or ID.
 * @param int|int[]    $product_ids Product and/or variation IDs.
 * @return bool
 */
function perfectpixel_order_has_product( $order, $product_ids ) {
	$order = $order instanceof WC_Order ? $order : wc_get_order( $order );
	$ids   = array_map( 'intval', (array) $product_ids );
	if ( ! $order || ! $ids ) {
		return false;
	}
	foreach ( $order->get_items() as $item ) {
		if ( in_array( (int) $item->get_product_id(), $ids, true ) || in_array( (int) $item->get_variation_id(), $ids, true ) ) {
			return true;
		}
	}
	return false;
}
